/* CSS Reset */
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    /* Root Variables - Customize for brand */
    :root {
      --primary-color: #1e5f8f;
      --secondary-color: #d4af37;
      --text-dark: #2c3e50;
      --text-light: #ffffff;
      --bg-light: #f8f9fa;
      --bg-white: #ffffff;
      --border-color: #dee2e6;
      --shadow: 0 2px 8px rgba(0,0,0,0.1);
      --transition: all 0.3s ease;
    }

    /* Typography */
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      line-height: 1.6;
      color: var(--text-dark);
      background-color: var(--bg-light);
    }

    h1, h2, h3 {
      font-weight: 700;
      line-height: 1.2;
      margin-bottom: 1rem;
    }

    h1 { font-size: 2.5rem; }
    h2 { font-size: 2rem; }
    h3 { font-size: 1.5rem; }

    /* Header */
    header {
      background-color: var(--primary-color);
      color: var(--text-light);
      padding: 1rem 0;
      position: sticky;
      top: 0;
      z-index: 1000;
      box-shadow: var(--shadow);
    }

    .header-container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 1rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .logo {
      font-size: 1.5rem;
      font-weight: 700;
    }

    .language-toggle {
      padding: 0.5rem 1rem;
      border: 2px solid var(--text-light);
      border-radius: 4px;
      background: transparent;
      color: var(--text-light);
      cursor: pointer;
      font-weight: 600;
      transition: var(--transition);
    }

    .language-toggle:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    .language-toggle:focus {
      outline: 2px solid var(--secondary-color);
      outline-offset: 2px;
    }

    [data-lang="es"] .lang-es,
    [data-lang="en"] .lang-en {
      display: none;
    }

    /* Main Layout */
    .bilingual-container {
      max-width: 1400px;
      margin: 0 auto;
      transition: var(--transition);
    }

    /* Desktop: Side-by-side */
    @media (min-width: 768px) {
      .bilingual-container {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 2rem;
        padding: 2rem 1rem;
      }

      .bilingual-container[data-lang="es"] .content-en {
        opacity: 0.3;
      }

      .bilingual-container[data-lang="en"] .content-es {
        opacity: 0.3;
      }
    }

    /* Mobile: Stacked with toggle */
    @media (max-width: 767px) {
      .bilingual-container {
        display: block;
        padding: 1rem;
      }

      .bilingual-container[data-lang="es"] .content-en {
        display: none;
      }

      .bilingual-container[data-lang="en"] .content-es {
        display: none;
      }
    }

    .content-es,
    .content-en {
      transition: opacity 0.3s ease;
    }

    /* Sections */
    section {
      background: var(--bg-white);
      padding: 2rem;
      margin-bottom: 2rem;
      border-radius: 8px;
      box-shadow: var(--shadow);
    }

    /* Hero Section */
    .hero {
      background: linear-gradient(135deg, var(--primary-color) 0%, #2c7fb8 100%);
      color: var(--text-light);
      text-align: center;
      padding: 3rem 2rem;
    }

    .hero h1 {
      margin-bottom: 0.5rem;
    }

    .hero-tagline {
      font-size: 1.25rem;
      margin-bottom: 2rem;
      opacity: 0.9;
    }

    /* Footer */
    footer {
      background-color: var(--text-dark);
      color: var(--text-light);
      padding: 2rem 1rem;
      text-align: center;
    }

    .footer-content {
      max-width: 1200px;
      margin: 0 auto;
    }

    .footer-note {
      font-size: 0.9rem;
      opacity: 0.8;
      margin-top: 1rem;
      padding-top: 1rem;
      border-top: 1px solid rgba(255, 255, 255, 0.1);
    }

    /* Accessibility */
    .skip-link {
      position: absolute;
      top: -40px;
      left: 0;
      background: var(--primary-color);
      color: var(--text-light);
      padding: 0.5rem 1rem;
      text-decoration: none;
      z-index: 100;
    }

    .skip-link:focus {
      top: 0;
    }

// Language toggle functionality (path-based routing)
    // Note: Language is determined by directory (/es/ or /en/)
    // The data-lang attribute is set on <html> element when generating each version
    (function() {
      const toggle = document.querySelector('.language-toggle');

      // Language toggle navigates to the other language version
      if (toggle) {
        toggle.addEventListener('click', () => {
          const currentLang = document.documentElement.getAttribute('data-lang');
          const targetLang = currentLang === 'es' ? 'en' : 'es';
          const currentPath = window.location.pathname;

          // Replace /es/ with /en/ or vice versa in the URL
          const newPath = currentPath.replace(/\/(es|en)\//, `/${targetLang}/`);
          window.location.href = newPath;
        });
      }
    })();

    // WebMCP Tool Definitions - Customize for your business
    window.mcpTools = {
      'toggle-language': {
        name: 'toggle-language',
        description: 'Switch between Spanish and English language versions',
        inputSchema: {
          type: 'object',
          properties: {
            lang: {
              type: 'string',
              enum: ['es', 'en'],
              description: 'Target language code'
            }
          },
          required: ['lang']
        },
        execute: async (params) => {
          const { lang } = params;
          const currentPath = window.location.pathname;

          // Navigate to the target language version (path-based)
          const newPath = currentPath.replace(/\/(es|en)\//, `/${lang}/`);
          window.location.href = newPath;

          return { success: true, targetLang: lang, targetUrl: newPath };
        }
      }
      // Add more WebMCP tools here for your business use cases
    };

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });
    });
